using System;using System.IO;using System.Net.WebSockets;using System.Text;using System.Threading;using System.Threading.Tasks;
namespace SarmatVisionHold.KestrelClient.Networking { public enum ConnectionState { Disconnected,Connecting,Connected } public sealed class KestrelWebSocketClient { readonly Uri uri;readonly bool reconnect;readonly SemaphoreSlim sendLock=new SemaphoreSlim(1,1);ClientWebSocket current;public ConnectionState State{get;private set;}public int ReconnectCount{get;private set;}public event Action<string> TextReceived;public event Action<byte[]> BinaryReceived;public event Action Connected,Disconnected;public KestrelWebSocketClient(string url,bool reconnect=true){uri=new Uri(url);this.reconnect=reconnect;}
 public async Task RunAsync(CancellationToken token){var delay=500;while(!token.IsCancellationRequested){try{State=ConnectionState.Connecting;using(var ws=new ClientWebSocket()){current=ws;await ws.ConnectAsync(uri,token);State=ConnectionState.Connected;delay=500;await Send(ws,"{\"type\":\"hello\",\"role\":\"consumer\",\"protocolVersion\":1}",token);Connected?.Invoke();await Receive(ws,token);}}catch(OperationCanceledException)when(token.IsCancellationRequested){break;}catch(Exception e){Console.Error.WriteLine("Kestrel connection: "+e.Message);}finally{current=null;if(State==ConnectionState.Connected)Disconnected?.Invoke();State=ConnectionState.Disconnected;}if(!reconnect)break;ReconnectCount++;try{await Task.Delay(delay,token);}catch(OperationCanceledException){break;}delay=Math.Min(5000,delay*2);}}
 public async Task<bool> SendTextAsync(string text,CancellationToken token){var ws=current;if(ws==null||ws.State!=WebSocketState.Open)return false;await sendLock.WaitAsync(token);try{if(ws.State!=WebSocketState.Open)return false;await Send(ws,text,token);return true;}finally{sendLock.Release();}}
 async Task Receive(ClientWebSocket ws,CancellationToken token){var chunk=new byte[64*1024];while(ws.State==WebSocketState.Open&&!token.IsCancellationRequested){using(var ms=new MemoryStream()){WebSocketReceiveResult r;do{r=await ws.ReceiveAsync(new ArraySegment<byte>(chunk),token);if(r.MessageType==WebSocketMessageType.Close)return;ms.Write(chunk,0,r.Count);if(ms.Length>8*1024*1024)throw new InvalidDataException("WebSocket message exceeds 8 MiB");}while(!r.EndOfMessage);var data=ms.ToArray();if(r.MessageType==WebSocketMessageType.Text)TextReceived?.Invoke(Encoding.UTF8.GetString(data));else BinaryReceived?.Invoke(data);}}}static Task Send(ClientWebSocket ws,string text,CancellationToken t){var b=Encoding.UTF8.GetBytes(text);return ws.SendAsync(new ArraySegment<byte>(b),WebSocketMessageType.Text,true,t);}
 } }
